(() => {const root = document.querySelector('.oliforge-country-settings');if (!root) return;const items = [...root.querySelectorAll('.oliforge-country-settings__item')];const boxes = items.map((item) => item.querySelector('input[type="checkbox"]'));const search = root.querySelector('#oliforge-country-settings-search');const count = root.querySelector('.oliforge-country-settings__count');const updateCount = () => { count.textContent = `${boxes.filter((box) => box.checked).length} / ${boxes.length}`; };root.querySelector('[data-oliforge-select-all]').addEventListener('click', () => { boxes.forEach((box) => { box.checked = true; }); updateCount(); });root.querySelector('[data-oliforge-clear-all]').addEventListener('click', () => { boxes.forEach((box) => { box.checked = false; }); updateCount(); });search.addEventListener('input', () => { const query = search.value.toLocaleLowerCase().trim(); items.forEach((item) => { item.hidden = query && !item.dataset.countrySearch.includes(query); }); });boxes.forEach((box) => box.addEventListener('change', updateCount));updateCount();})();